xml.Script:
        Colors[0] := 'FF7700'; // Orange
        Colors[1] := 'FFFFFF'; // White
        Colors[2] := 'FFFF00'; // Yellow

        R := 0.6;
        H := R * 0.5;
        A := 0.9; // incline

        N := 40;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        for i := 0 to 2 do begin
            ax[i] := cos(2 * Pi / 3 * i);
            ay[i] := sin(2 * Pi / 3 * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i;
i2 := (i + 1) mod N;
Inc(i);
